DURATION = re.compile(r"^([0-9]+(ns|us|ms|s|m|h))+$")
_DURATION_PART = re.compile(r"([0-9]+)(ns|us|ms|s|m|h)")
_NS = {"ns": 1, "us": 1000, "ms": 10**6, "s": 10**9, "m": 60 * 10**9, "h": 3600 * 10**9}


def duration_ns(d: str) -> int:
    return sum(int(n) * _NS[u] for n, u in _DURATION_PART.findall(d))


def render_duration(d: str, encoding: str | None = "go") -> str:
    """A duration in its encoding (#RenderDuration)."""
    if (encoding or "go") == "go" or not DURATION.match(d):
        return d
    ms = duration_ns(d) // 10**6
    secs, frac = divmod(ms, 1000)
    frac_str = "" if frac == 0 else "." + f"{frac:03d}".rstrip("0")
    if encoding == "seconds":
        return f"{secs}{frac_str}"
    if encoding == "iso8601":
        return f"PT{secs}{frac_str}S"
    days = secs // 86400
    return f"{f'{days}.' if days > 0 else ''}{(secs % 86400) // 3600:02d}:{(secs % 3600) // 60:02d}:{secs % 60:02d}{frac_str}"


def _plain(x: Any) -> Any:
    """x with whole floats as ints, so JSON writes 2 as #Render does, not 2.0."""
    if isinstance(x, float) and x.is_integer() and abs(x) < 2**53:
        return int(x)
    if isinstance(x, dict):
        return {k: _plain(v) for k, v in x.items()}
    if isinstance(x, (list, tuple)):
        return [_plain(v) for v in x]
    return x


def marshal(x: Any) -> str:
    """JSON as #Render writes it: compact, with U+2028 and U+2029 escaped."""
    s = json.dumps(_plain(x), separators=(",", ":"), ensure_ascii=False)
    return s.replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")


def esc(s: str) -> str:
    """Kubernetes expands $(VAR) in env values and reduces $$ to $, so every $ is doubled."""
    return s.replace("$", "$$")


def wire_entries(name: str, v: Obj, x: Any) -> list[tuple[str, str]]:
    """A literal's env entries as the app reads them, before Kubernetes escaping (#RenderVar)."""
    t = v["type"]
    if t == "json":
        return [(name, marshal(x))]
    if t == "list":
        items = list(x) if isinstance(x, (list, tuple)) else [x]
        enc = v.get("encoding") or "csv"
        if enc == "json":
            return [(name, marshal(items))]
        if enc == "indexed":
            return [(f"{name}__{i}", js(item)) for i, item in enumerate(items)]
        return [(name, (v.get("separator") or ",").join(js(i) for i in items))]
    if t == "duration":
        return [(name, render_duration(js(x), v.get("encoding")))]
    return [(name, js(x))]


_VALUE_FROM = {"secretKeyRef": "secret_key_ref", "configMapKeyRef": "config_map_key_ref", "fieldRef": "field_ref", "resourceFieldRef": "resource_field_ref"}
_KEYS = {"fieldPath": "field_path", "containerName": "container_name"}


def _value_from(kind: str, src: Obj) -> Obj:
    return {_VALUE_FROM[kind]: {_KEYS.get(k, k): x for k, x in src.items() if x is not None}}


def render_var(name: str, v: Obj, arg: Obj) -> list[Obj]:
    kind = source_of(arg, VAR_SOURCES)
    src = arg[kind]
    if kind == "injected":
        ref = src.get("ref")
        return [{"name": name, "value": esc(ref)}] if isinstance(ref, str) and ref != "" else []
    if kind != "value":
        return [{"name": name, "value_from": _value_from(kind, src)}]
    return [{"name": n, "value": esc(x)} for n, x in wire_entries(name, v, src)]


# ---- Files (#RenderFile) ----


def mount_dir(f: Obj) -> str:
    return f["path"] if f["type"] == "tls" else posixpath.dirname(f["path"])


def inline_content(f: Obj, inline: Any) -> str:
    """The text an inline source puts in the file (#InlineContent)."""
    if isinstance(inline, str):
        return inline
    fmt = f.get("format")
    if fmt == "json":
        return marshal(inline)
    if fmt == "toml":
        return tomli_w.dumps(_plain(inline))
    return yaml.safe_dump(_plain(inline), sort_keys=False, allow_unicode=True, default_flow_style=False)


def hash10(s: str) -> str:
    return hashlib.sha256(s.encode()).hexdigest()[:10]


def _parts() -> Obj:
    return {"env": [], "volumes": [], "volume_mounts": [], "config_maps": [], "restart_triggers": []}


def render_file(service: str, name: str, f: Obj, arg: Obj) -> Obj:
    kind = source_of(arg, FILE_SOURCES)
    s = arg[kind]
    vol = f"dc-{name}"
    file_name = posixpath.basename(f["path"])
    mode = 0o400 if f.get("secret") else 0o444
    out = _parts()
    if f.get("pathEnv"):
        out["env"].append({"name": f["pathEnv"], "value": esc(f["path"])})
    if kind == "injected":
        return out

    def restart(k: str, n: Any) -> None:
        if f.get("reload") == "restart":
            out["restart_triggers"].append({"kind": k, "name": n})

    if kind == "inline":
        content = inline_content(f, s)
        cm = f"{service}-{name}-{hash10(content)}"
        volume = {"name": vol, "config_map": {"name": cm, "default_mode": mode, "items": [{"key": file_name, "path": file_name}]}}
        out["config_maps"].append({"name": cm, "data": {file_name: content}, "immutable": True})
    elif kind == "configMap":
        volume = {"name": vol, "config_map": {"name": s["name"], "default_mode": mode, "items": [{"key": s["key"], "path": file_name}]}}
        restart("ConfigMap", s["name"])
    elif kind == "secret":
        secret: Obj = {"secret_name": s["name"], "default_mode": mode}
        if f["type"] != "tls":
            secret["items"] = [{"key": s["key"], "path": file_name}]
        volume = {"name": vol, "secret": secret}
        restart("Secret", s["name"])
    elif kind == "certificate":
        volume = {"name": vol, "secret": {"secret_name": s["secretName"], "default_mode": mode}}
        restart("Secret", s["secretName"])
    elif kind == "image":
        image: Obj = {"reference": s["reference"]}
        if s.get("pullPolicy"):
            image["pull_policy"] = s["pullPolicy"]
        volume = {"name": vol, "image": image}
    else:  # csi
        spc = s["secretProviderClass"]
        volume = {"name": vol, "csi": {"driver": s.get("driver") or "secrets-store.csi.k8s.io", "read_only": True, "volume_attributes": {"secretProviderClass": spc}}}
        restart("SecretProviderClass", spc)
    out["volumes"].append(volume)
    out["volume_mounts"].append({"name": vol, "mount_path": mount_dir(f), "read_only": True})
    return out


# ---- Overlays (#RenderOverlay) ----


def overlay_native(v: Obj, x: Any) -> Any:
    """A value as an overlay writes it: native types, a duration in its encoding (#OverlayData)."""
    if v["type"] != "duration" or not isinstance(x, str):
        return x
    if v.get("encoding") == "seconds":
        ms = duration_ns(x) // 10**6
        return ms // 1000 if ms % 1000 == 0 else ms / 1000
    return render_duration(x, v.get("encoding"))


def overlay_data(c: Obj, o: Obj, values: Obj) -> Obj:
    out: Obj = {}
    for n in sorted(values):
        v = c["vars"][n]
        parts = (v.get("configKey") or n).split(o["keySeparator"])
        at = out
        for p in parts[:-1]:
            at = at.setdefault(p, {})
        at[parts[-1]] = overlay_native(v, values[n])
    return out


def render_overlay(c: Obj, name: str, o: Obj, values: Obj) -> tuple[Obj, Obj, Obj]:
    data = overlay_data(c, o, values)
    if o["format"] == "json":
        content = json.dumps(_plain(data), indent=2, ensure_ascii=False) + "\n"
    elif o["format"] == "yaml":
        content = yaml.safe_dump(_plain(data), sort_keys=False, allow_unicode=True, default_flow_style=False)
    else:
        content = tomli_w.dumps(_plain(data))
    file_name = posixpath.basename(o["path"])
    watch = o.get("reload") == "watch"
    service = c["metadata"]["name"]
    cm = f"{service}-overlay-{name}" if watch else f"{service}-overlay-{name}-{hash10(content)}"
    spec: Obj = {"name": cm, "data": {file_name: content}}
    if not watch:
        spec["immutable"] = True
    volume = {"name": f"dc-overlay-{name}", "config_map": {"name": cm, "default_mode": 0o444, "items": [{"key": file_name, "path": file_name}]}}
    mount = {"name": f"dc-overlay-{name}", "mount_path": posixpath.dirname(o["path"]), "read_only": True}
    return spec, volume, mount


# ---- Pod metadata (#PodMetadata) ----

PLACEHOLDER = re.compile(r"\{(input|path|dir|file)\}")
QUALIFIED = re.compile(r"^([a-z0-9]([-a-z0-9]*[a-z0-9])?(\.[a-z0-9]([-a-z0-9]*[a-z0-9])?)*/)?[A-Za-z0-9]([-A-Za-z0-9_.]{0,61}[A-Za-z0-9])?$")
QUALIFIED_LEN = re.compile(r"^([^/]{1,253}/)?[^/]+$")
LABEL_VALUE = re.compile(r"^([A-Za-z0-9]([-A-Za-z0-9_.]{0,61}[A-Za-z0-9])?)?$")
QUALIFIED_RULE = 'a Kubernetes qualified name: an optional DNS-subdomain prefix (at most 253 characters) and "/", then at most 63 letters, digits, "-", "_" and ".", starting and ending with a letter or digit'
LABEL_RULE = 'at most 63 letters, digits, "-", "_" and ".", starting and ending with a letter or digit, or empty'
PROVIDER = re.compile(r"^[a-z0-9]([-a-z0-9.]{0,61}[a-z0-9])?$")
FIELD_PATH = re.compile(r"^(metadata\.name|metadata\.namespace|metadata\.uid|spec\.nodeName|spec\.serviceAccountName|status\.hostIP|status\.podIP|metadata\.(labels|annotations)\['[^']+'\])$")
RESOURCES = ["limits.cpu", "limits.memory", "limits.ephemeral-storage", "requests.cpu", "requests.memory", "requests.ephemeral-storage"]


def _expand(s: str, inp: str | None, f: Obj | None) -> str:
    if inp is not None:
        s = s.replace("{input}", inp)
    if f is not None:
        s = s.replace("{path}", f["path"]).replace("{dir}", mount_dir(f)).replace("{file}", posixpath.basename(f["path"]))
    return s


def _pod_source(inp: str | None, f: Obj | None, annotations: Any, labels: Any) -> Obj:
    def ex(m: Any) -> dict[str, str]:
        return {_expand(k, inp, f): _expand(js(v), inp, f) for k, v in (m or {}).items()}

    return {"input": inp, "file": f, "annotations": ex(annotations), "labels": ex(labels)}


def pod_problems(sources: list[Obj]) -> list[str]:
    out: list[str] = []
    for s in sources:
        who = s["input"]
        for field, m in (("podAnnotations", s["annotations"]), ("podLabels", s["labels"])):
            for k, v in m.items():
                if PLACEHOLDER.search(k) or PLACEHOLDER.search(v):
                    if who is None:
                        out.append(f"{field} {k}: uses a placeholder, which only an injected input's own podAnnotations and podLabels can")
                    elif s["file"] is not None:
                        out.append(f"{who}: {field} {k}: uses a placeholder this input does not define")
                    else:
                        out.append(f"{who}: {field} {k}: uses {{path}}, {{dir}} or {{file}}, which only a file input defines; a variable has {{input}}")
                    continue
                what = "annotation" if field == "podAnnotations" else "label"
                if not QUALIFIED.match(k) or not QUALIFIED_LEN.match(k):
                    out.append(f"{field}: key {quote(k)} is not {QUALIFIED_RULE}" if who is None else f"{who}: pod {what} key {quote(k)} is not {QUALIFIED_RULE}")
                elif field == "podLabels" and not LABEL_VALUE.match(v):
                    out.append(
                        f"podLabels {k}: value {quote(v)} is not a label value: {LABEL_RULE}" if who is None else f"{who}: pod label {k}: value {quote(v)} is not a label value: {LABEL_RULE}"
                    )
    # Two sources that set one key to different values (#PodMetadataConflicts).
    for field in ("annotations", "labels"):
        seen: dict[str, Obj] = {}
        for s in sources:
            for k, v in s[field].items():
                first = seen.get(k)
                if first is None:
                    seen[k] = s
                elif first[field][k] != v:
                    a, b = sorted([first["input"] or f"the shared podMetadata.{field}", s["input"] or f"the shared podMetadata.{field}"])
                    out.append(f"pod{'Annotations' if field == 'annotations' else 'Labels'} {k}: set to different values by {a} and {b}")
    return out


def _pod_sources(c: Obj, args: Obj, pod_metadata: Obj) -> list[Obj]:
    """The pod metadata sources, in #Render's order: shared, then variables, then file inputs."""
    out = [_pod_source(None, None, pod_metadata.get("annotations"), pod_metadata.get("labels"))]
    for n in c["vars"]:
        a = args.get(n)
        if is_obj(a) and is_obj(a.get("injected")):
            out.append(_pod_source(n, None, a["injected"].get("podAnnotations"), a["injected"].get("podLabels")))
    for n, f in (c.get("files") or {}).items():
        a = args.get(n)
        if is_obj(a) and is_obj(a.get("injected")):
            out.append(_pod_source(n, f, a["injected"].get("podAnnotations"), a["injected"].get("podLabels")))
    return out


# ---- Rendering: arguments with every Input resolved ----


def render(c: Obj, args: Obj, overlay_values: Obj, pod_metadata: Obj) -> Obj:
    """#Render, for arguments that passed the checks."""
    env: list[Obj] = []
    for n, v in c["vars"].items():
        if is_obj(args.get(n)):
            env += render_var(n, v, args[n])
    files = [render_file(c["metadata"]["name"], n, f, args[n]) for n, f in (c.get("files") or {}).items() if is_obj(args.get(n))]
    overlays = [render_overlay(c, n, o, overlay_values[n]) for n, o in (c.get("overlays") or {}).items() if overlay_values.get(n) is not None]
    annotations: dict[str, str] = {}
    labels: dict[str, str] = {}
    for s in _pod_sources(c, args, pod_metadata):
        annotations.update(s["annotations"])
        labels.update(s["labels"])
    return {
        "env": env + [e for f in files for e in f["env"]],
        "volumes": [v for f in files for v in f["volumes"]] + [o[1] for o in overlays],
        "volume_mounts": [m for f in files for m in f["volume_mounts"]] + [o[2] for o in overlays],
        "config_maps": [m for f in files for m in f["config_maps"]] + [o[0] for o in overlays],
        "restart_triggers": [t for f in files for t in f["restart_triggers"]],
        "pod_annotations": annotations,
        "pod_labels": labels,
    }


# ---- Checks, with the SDK ----

_empty_root: str | None = None


def _no_files() -> str:
    """A file root holding nothing, so value checks never read the deploying machine's files."""
    global _empty_root
    if _empty_root is None:
        _empty_root = tempfile.mkdtemp(prefix="docuconf-")
    return _empty_root


def _check(c: Obj, env: Mapping[str, str], root: str) -> tuple[list[Any], list[str]]:
    """The SDK's violations and warnings for env, as the app would report them at boot."""
    contract = {k: x for k, x in c.items() if k != "overlays"}
    with warnings.catch_warnings(record=True) as caught:
        warnings.simplefilter("always")
        try:
            docuconf.load_contract(contract, env={**env, "DOCUCONF_FILE_ROOT": root}, termination_log=False, watch=False)
            violations: list[Any] = []
        except docuconf.ConfigValidationError as e:
            violations = list(e.violations)
    return violations, [str(w.message) for w in caught if issubclass(w.category, docuconf.DocuconfWarning)]


def value_problems(c: Obj, name: str, x: Any, suffix: str = "") -> tuple[list[str], list[str]]:
    """A literal's problems, as the app would report them at boot."""
    v = c["vars"][name]
    # What the SDK cannot see in the rendered text: precision a duration's
    # encoding drops, and an empty list, which renders as an unset variable.
    if v["type"] == "duration" and isinstance(x, str) and DURATION.match(x) and (v.get("encoding") or "go") != "go" and duration_ns(x) % 10**6 != 0:
        return [f"{name}: {x} is finer than a millisecond, which the {v['encoding']} encoding cannot carry (invalid_type){suffix}"], []
    if v["type"] == "list" and isinstance(x, (list, tuple)) and len(x) == 0:
        m = v.get("minItems")
        return ([f"{name}: must have at least {m} items, has 0 (too_few_items){suffix}"] if isinstance(m, int) and m > 0 else []), []
    violations, warned = _check(c, dict(wire_entries(name, v, x)), _no_files())
    problems = [f"{name}: {p.message} ({p.code}){suffix}" for p in violations if p.input == name and p.code != "missing_required"]
    return problems, [w for w in warned if w.startswith(name + " ") or w.startswith(name + ":")]


def inline_problems(c: Obj, name: str, content: str) -> list[str]:
    """Inline file content's problems, as the app would report them at boot."""
    f = c["files"][name]
    root = tempfile.mkdtemp(prefix="docuconf-")
    try:
        path = os.path.join(root, f["path"].lstrip("/"))
        os.makedirs(os.path.dirname(path), exist_ok=True)
        with open(path, "w", encoding="utf-8") as fh:
            fh.write(content)
        violations, _ = _check(c, {}, root)
        return [f"{name}: {p.message} ({p.code})" for p in violations if p.input == name]
    finally:
        shutil.rmtree(root, ignore_errors=True)


def overlay_reason(c: Obj, n: str, o: str) -> str | None:
    """Why a variable cannot go in an overlay, in vet's words."""
    v = c["vars"].get(n)
    if v is None:
        return f"is not declared in the contract (check the spelling; in overlay {o})"
    if is_secret(v):
        return f"is secret, so it cannot go in overlay {o} (a ConfigMap); supply it in the environment as a secretKeyRef or injected"
    if not v.get("configKey"):
        return f"has no configKey in the contract, so overlay {o} has nowhere to put it"
    if (c.get("profiles") or {}).get("selector") == n:
        return f"is the profile selector, which only the environment can set, not overlay {o}"
    if len(v["configKey"].split(c["overlays"][o]["keySeparator"])) > 8:
        return f"configKey {v['configKey']} is nested deeper than 8 levels"
    return None


def profile_supplies(c: Obj, n: str) -> bool:
    return any(n in m for m in ((c.get("profiles") or {}).get("defaults") or {}).values())


def deprecated_warning(n: str, d: Obj) -> str:
    """The SDK's deprecation warning."""
    by = f" (replaced by {d['replacedBy']})" if d.get("replacedBy") is not None and d["replacedBy"] not in d["message"] else ""
    return f"{n} is deprecated: {d['message']}{by}"


def overlay_type_problem(v: Obj, x: Any) -> str | None:
    """An overlay value of the wrong native type, with vet's message."""
    got = f"got {quote(x)}"
    t = v["type"]
    is_int = isinstance(x, int) and not isinstance(x, bool)
    if t == "int":
        return None if is_int or (isinstance(x, float) and x.is_integer()) else f"expected an integer, {got}"
    if t == "float":
        return None if is_int or isinstance(x, float) else f"expected a number, {got}"
    if t == "bool":
        return None if isinstance(x, bool) else f"expected true or false, {got}"
    if t == "json":
        return None
    if t == "list":
        ints = v.get("items") == "int"
        ok = isinstance(x, list) and all((isinstance(i, int) and not isinstance(i, bool)) if ints else isinstance(i, str) for i in x)
        return None if ok else f"expected a list of {v.get('items') or 'string'}s, {got}"
    if t == "url":
        return None if isinstance(x, str) else f"expected a URL string, {got}"
    return None if isinstance(x, str) else f"expected a string, {got}"


def certificate_problems(n: str, f: Obj, s: Obj) -> list[str]:
    out: list[str] = []
    names = s.get("dnsNames")
    if isinstance(names, list) and not has_output(names):
        for d in f.get("dnsNames") or []:
            i = d.find(".")
            wildcard = "*" + d[i:] if i >= 0 else ""
            if d not in names and wildcard not in names:
                out.append(f"{n}: certificate does not cover {d}")
    alg = (s.get("privateKey") or {}).get("algorithm")
    if f.get("keyAlgorithms") and isinstance(alg, str) and alg not in f["keyAlgorithms"]:
        out.append(f"{n}: certificate key algorithm {alg} is not one of {', '.join(f['keyAlgorithms'])}")
    for field in ("duration", "renewBefore"):
        x = s.get(field)
        if isinstance(x, str) and not DURATION.match(x):
            out.append(f"{n}: certificate.{field} {quote(x)} is not a duration such as 1m30s")
    rb = s.get("renewBefore")
    if f.get("minRemaining") and isinstance(rb, str) and DURATION.match(rb) and duration_ns(rb) < duration_ns(f["minRemaining"]):
        out.append(f"{n}: certificate renewBefore {rb} is less than minRemaining {f['minRemaining']}, so the app could see a certificate with too little time left")
    return out


def structure_problems(c: Obj, args: Obj, overlay_values: Obj, pod_metadata: Any) -> tuple[list[str], list[str]]:
    """The checks that need no resolved Input: which arguments and sources are
    set, inline content, overlays, and anything else the program writes as a
    literal. Returns the problems and the deprecation warnings."""
    problems: list[str] = []
    warned: list[str] = []
    files = c.get("files") or {}
    overlays = c.get("overlays") or {}
    for k, a in args.items():
        if a is not None and k not in c["vars"] and k not in files:
            problems.append(f"{k}: is not declared in the contract")

    def in_overlay(n: str) -> list[str]:
        return [o for o in overlays if is_obj(overlay_values.get(o)) and overlay_values[o].get(n) is not None]

    for n, v in c["vars"].items():
        a = args.get(n)
        srcs = var_sources(v)
        if a is None:
            if v.get("required") and not in_overlay(n) and not profile_supplies(c, n):
                problems.append(f"{n}: required, but not set (missing_required)")
            continue
        if isinstance(a, pulumi.Output):
            problems.append(f'{n}: give the source as a dict, such as {{"value": ...}}, with any Output inside it')
            continue
        kind = source_of(a, VAR_SOURCES)
        if kind is None or kind not in srcs:
            if is_obj(a) and "value" in a and is_secret(v):
                problems.append(f"{n}: is secret, so it is never a value; set it with {or_list(srcs)}")
            else:
                problems.append(f"{n}: set exactly one of {or_list(srcs)}")
            continue
        s = a[kind]
        if kind == "injected" and is_obj(s) and not has_output(s.get("provider")) and not PROVIDER.match(js(s.get("provider") or "")):
            problems.append(f"{n}: injected.provider must name the injector as a lowercase label, such as bank-vaults")
        if kind == "injected" and is_obj(s) and s.get("ref") is not None and v["type"] in ("keySet", "list") and (v.get("encoding") or "csv") == "indexed":
            problems.append(f"{n}: an indexed list is spread over NAME__0, NAME__1, …, so one injected reference cannot carry it; let the injector set the variables, without ref")
        if kind == "fieldRef" and is_obj(s) and not has_output(s.get("fieldPath")) and not FIELD_PATH.match(js(s.get("fieldPath"))):
            problems.append(f"{n}: fieldRef.fieldPath {quote(s.get('fieldPath'))} is not a Downward API field")
        if kind == "resourceFieldRef" and is_obj(s) and not has_output(s.get("resource")) and js(s.get("resource")) not in RESOURCES:
            problems.append(f"{n}: resourceFieldRef.resource {quote(s.get('resource'))} is not a container resource")
        # The SDK warns about a deprecated value it checks; a reference it
        # never sees is warned about here.
        if v.get("deprecated") and kind != "value":
            warned.append(deprecated_warning(n, v["deprecated"]))
        # A plain literal is checked now, with the others, so every problem
        # is reported at once; an Output is checked when it resolves.
        if kind == "value" and not has_output(s):
            p, w = value_problems(c, n, s)
            problems += p
            warned += w
        for o in in_overlay(n):
            problems.append(f"{n}: is set both in the environment and in overlay {o}; set it in one place (the environment would win)")

    for n, f in files.items():
        a = args.get(n)
        srcs = file_sources(f)
        if a is None:
            if f.get("required"):
                problems.append(f"{n}: is a required file input; set one of {or_list(srcs)}")
            continue
        kind = source_of(a, FILE_SOURCES)
        if kind is None or kind not in srcs:
            problems.append(f"{n}: set exactly one of {or_list(srcs)}{' (a secret file comes from a secret store)' if f.get('secret') else ''}")
            continue
        s = a[kind]
        file_name = posixpath.basename(f["path"])
        if f.get("deprecated"):
            warned.append(deprecated_warning(n, f["deprecated"]))
        if kind == "inline":
            if has_output(s):
                problems.append(f"{n}: inline content is written into the platform's code; give it as a value, not an Output")
                continue
            if not isinstance(s, str) and f["type"] != "config":
                problems.append(f"{n}: inline content must be text for a {f['type']} file")
                continue
            if not isinstance(s, (str, dict, list)):
                problems.append(f"{n}: inline content must be text, or a dict or a list to write as {f.get('format')}")
                continue
            problems += inline_problems(c, n, inline_content(f, s))
            continue
        if not is_obj(s):
            problems.append(f"{n}: {kind} must be a dict")
            continue
        if kind in ("configMap", "secret") and f["type"] != "tls" and s.get("key") is None:
            problems.append(f"{n}: {kind}.key is required: name the key that holds {file_name}")
        if kind == "secret" and f["type"] == "tls" and s.get("key") is not None:
            problems.append(f"{n}: a tls input mounts the whole Secret; remove secret.key")
        if kind == "injected" and not has_output(s.get("provider")) and not PROVIDER.match(js(s.get("provider") or "")):
            problems.append(f"{n}: injected.provider must name the injector as a lowercase label, such as bank-vaults")
        if kind == "image" and s.get("pullPolicy") is not None and s["pullPolicy"] not in ("Always", "IfNotPresent", "Never"):
            problems.append(f"{n}: image.pullPolicy {quote(s['pullPolicy'])} is not one of Always, IfNotPresent, Never")
        if kind == "certificate":
            problems += certificate_problems(n, f, s)

    for o, values in overlay_values.items():
        if values is None:
            continue
        if o not in overlays:
            problems.append(f"overlay_values.{o}: is not an overlay in the contract")
            continue
        if not is_obj(values) or has_output(values):
            problems.append(f"overlay_values.{o}: must be a dict of variable names and values, written into the platform's code (no Outputs)")
            continue
        for n, x in values.items():
            if x is None:
                continue
            why = overlay_reason(c, n, o)
            if why is not None:
                problems.append(f"{n}: {why}")
                continue
            if is_obj(x) and any(k != "value" and k in x for k in VAR_SOURCES):
                problems.append(f"{n}: overlay {o} holds values, not references; give a literal, or supply the reference in the environment")
                continue
            tp = overlay_type_problem(c["vars"][n], x)
            if tp is not None:
                problems.append(f"{n}: {tp} (in overlay {o})")
                continue
            p, w = value_problems(c, n, x, f" (in overlay {o})")
            problems += p
            warned += w
    for n in c["vars"]:
        if len(in_overlay(n)) > 1:
            problems.append(f"{n}: is set in more than one overlay; set it in one place")
    # Pod metadata written as literals is checked now; with an Output in
    # it, when it resolves.
    if not has_output(pod_metadata) and not problems:
        sources = _pod_sources(c, args, pod_metadata or {})
        if not any(has_output(s["annotations"]) or has_output(s["labels"]) for s in sources):
            problems += pod_problems(sources)
    return problems, warned


# ---- The component's outputs ----


def bindings(c: Obj, args: Obj, overlay_values: Obj, names: list[str] | None = None, kinds: tuple[str, ...] = VAR_SOURCES) -> Obj:
    """Which source sets each input (the bindings output)."""
    out: Obj = {}
    overlays = c.get("overlays") or {}
    for n in c["vars"]:
        o = next((o for o in overlays if is_obj(overlay_values.get(o)) and overlay_values[o].get(n) is not None), None)
        kind = source_of(args.get(n), kinds)
        out[n] = {"set": kind is not None or o is not None, "source": kind or (f"overlay:{o}" if o else None)}
    for n in names if names is not None else list(c.get("files") or {}):
        kind = source_of(args.get(n), FILE_SOURCES if kinds is VAR_SOURCES else ("secret", "injected"))
        out[n] = {"set": kind is not None, "source": kind}
    return out


def _clean(args: Mapping[str, Any] | None) -> Obj:
    return {k: x for k, x in (args or {}).items() if x is not None}


def _checked_values(self: pulumi.Resource, c: Obj, args: Obj, names: list[str], kinds: tuple[str, ...]) -> dict[str, pulumi.Output[Any]]:
    """Each argument as an Output of its resolved source. A value that is an
    Output is checked on its own, as soon as it resolves, so a bad one known
    at preview fails the preview even when another is not known yet."""
    component = f"{c['metadata']['name']} config"
    out: dict[str, pulumi.Output[Any]] = {}
    for n in names:
        a = args.get(n)
        if not is_obj(a):
            continue
        kind = source_of(a, kinds)
        later = kind == "value" and has_output(a[kind])

        def check(x: Any, n: str = n, kind: str = kind, later: bool = later) -> Obj:
            if later:
                p, w = value_problems(c, n, x)
                if p:
                    raise ConfigViolation(component, p)
                for m in w:
                    pulumi.log.warn(m, self)
            return {kind: x}

        out[n] = pulumi.Output.from_input(a[kind]).apply(check)
    return out


def kubernetes(self: pulumi.Resource, c: Obj, args: Mapping[str, Any], overlay_values: Mapping[str, Any] | None, pod_metadata: Any) -> Obj:
    """Checks and renders a component's arguments on kubernetes. Problems that
    need no resolved Input raise a ConfigViolation at once; a value's problems
    raise one when it resolves, which fails every output."""
    component = f"{c['metadata']['name']} config"
    args = _clean(args)
    overlay_values = _clean(overlay_values)
    problems, warned = structure_problems(c, args, overlay_values, pod_metadata)
    if problems:
        raise ConfigViolation(component, problems)
    for w in warned:
        pulumi.log.warn(w, self)
    checked = _checked_values(self, c, args, list(c["vars"]), VAR_SOURCES)
    file_args = {n: args[n] for n in c.get("files") or {} if n in args}

    def finish(xs: list[Any]) -> Obj:
        vars_, files, pod = xs
        resolved = {**vars_, **files}
        p = pod_problems(_pod_sources(c, resolved, pod or {}))
        if p:
            raise ConfigViolation(component, p)
        return render(c, resolved, overlay_values, pod or {})

    rendered = pulumi.Output.all(pulumi.Output.all(**checked) if checked else pulumi.Output.from_input({}), pulumi.Output.from_input(file_args), pulumi.Output.from_input(pod_metadata or {})).apply(finish)
    # ConfigMaps hold only literals, so they are known now, and the program
    # can declare one resource for each.
    literal = {n: a for n, a in file_args.items() if source_of(a, FILE_SOURCES) == "inline"}
    config_maps = render(c, literal, overlay_values, {})["config_maps"]
    return {
        "kubernetes_env": rendered.apply(lambda r: r["env"]),
        "kubernetes_volumes": rendered.apply(lambda r: r["volumes"]),
        "kubernetes_volume_mounts": rendered.apply(lambda r: r["volume_mounts"]),
        "kubernetes_config_maps": config_maps,
        "restart_triggers": rendered.apply(lambda r: r["restart_triggers"]),
        "pod_annotations": rendered.apply(lambda r: r["pod_annotations"]),
        "pod_labels": rendered.apply(lambda r: r["pod_labels"]),
        "bindings": bindings(c, args, overlay_values),
        "checked": pulumi.Output.all(*checked.values(), rendered).apply(lambda _: True),
    }


# ---- The ecs, cloudrun and containerapps targets (spec/IAC.md 5.1-5.3) ----
#
# A variable is a literal, a reference the platform resolves when the task
# or instance starts, or injected. ECS mounts no files; Cloud Run mounts a
# file input from a Secret Manager secret, and Container Apps from a Key
# Vault secret, one file per secret. ECS and Cloud Run do not expand
# $(VAR); Container Apps runs on Kubernetes and does, so its values are
# escaped as the kubernetes target's are.

SM_ARN = re.compile(r"^arn:aws(-cn|-us-gov|-iso|-iso-b)?:secretsmanager:[a-z0-9-]+:[0-9]{12}:secret:[A-Za-z0-9/_+=.@-]+$")
SSM_ARN = re.compile(r"^arn:aws(-cn|-us-gov|-iso|-iso-b)?:ssm:[a-z0-9-]+:[0-9]{12}:parameter/[A-Za-z0-9/_.-]+$")
BARE_REF = re.compile(r"^[A-Za-z0-9/_+=.@-]+$")
GCP_SECRET = re.compile(r"^(projects/[a-z][a-z0-9-]{4,28}[a-z0-9]/secrets/)?[A-Za-z0-9_-]{1,255}$")
GCP_VERSION = re.compile(r"^(latest|[1-9][0-9]*)$")
KEY_VAULT_SECRET_ID = re.compile(r"^https://[0-9A-Za-z-]{3,24}\.vault\.[0-9a-z.-]+/secrets/[0-9A-Za-z-]{1,127}(/[0-9A-Fa-f]{32})?/?$")
AZURE_IDENTITY = re.compile(r"^(System|(?i:/subscriptions/[^/]+/resourceGroups/[^/]+/providers/Microsoft\.ManagedIdentity/userAssignedIdentities/[^/]+))$")
PLATFORM = {"ecs": "ECS", "cloudrun": "Cloud Run", "containerapps": "Container Apps", "lambda": "Lambda"}
LAMBDA_ENV_LIMIT = 4096  # the size Lambda allows a function's environment variables, keys and values together
TARGET_SOURCES = ("value", "secret", "injected")


def target_var_sources(v: Obj, target: str = "") -> list[str]:
    """The sources a variable accepts on ecs, cloudrun and containerapps; on lambda, which resolves
    no secret references, a secret is injected."""
    if target == "lambda" and is_secret(v):
        return ["injected"]
    # One variable per key: no single secret carries it, but an injector can set the variables.
    if is_secret(v) and v.get("encoding") == "indexed":
        return ["injected"]
    return ["secret", "injected"] if is_secret(v) else ["value", "injected"]


def target_files(c: Obj, target: str) -> list[tuple[str, Obj]]:
    """The file inputs a target can deliver: none on ecs; on cloudrun and containerapps, all but tls directories."""
    if target in ("ecs", "lambda"):
        return []
    return [(n, f) for n, f in (c.get("files") or {}).items() if f["type"] != "tls"]


def ecs_value_from(s: Obj) -> str:
    """secrets[].valueFrom as ECS takes it: the ARN, then any selectors (arn:json-key:stage:id)."""
    sel = [s.get("jsonKey"), s.get("versionStage"), s.get("versionId")]
    if all(x is None for x in sel):
        return s["valueFrom"]
    return f"{s['valueFrom']}:" + ":".join("" if x is None else js(x) for x in sel)


def _secret_hint(target: str, v: Obj, srcs: list[str]) -> str:
    if target == "lambda" and is_secret(v):
        return " (Lambda resolves no secret references, so a secret is injected: give the secret's ARN as ref, and the function reads it)"
    what = {"ecs": "one ECS secret", "cloudrun": "one secret version", "containerapps": "one secret", "lambda": "one secret"}[target]
    if is_secret(v) and "secret" not in srcs:
        return f" (an indexed key set is one variable per key, which {what} cannot carry)"
    if is_secret(v):
        return " (a secret is never a literal value)"
    return f" ({PLATFORM[target]} has no ConfigMaps or Downward API)"


def app_secret_name(name: str, file: bool) -> str:
    """The name of the app secret the containerapps component adds for an input: lower case
    letters, digits and -, as Container Apps requires (dc-database-url for DATABASE_URL,
    dc-file-NAME for a file input)."""
    slug = re.sub(r"[^a-z0-9]+", "-", name.lower()).strip("-")
    return ("dc-file-" if file else "dc-") + slug


def _key_vault_problems(n: str, s: Obj) -> list[str]:
    out: list[str] = []
    sid = s.get("keyVaultSecretId")
    if not has_output(sid) and not KEY_VAULT_SECRET_ID.match(js(sid or "")):
        out.append(f"{n}: secret.keyVaultSecretId {quote(sid)} is not a Key Vault secret ID, such as https://VAULT.vault.azure.net/secrets/NAME")
    identity = s.get("identity") or "System"
    if not has_output(identity) and not AZURE_IDENTITY.match(js(identity)):
        out.append(f"{n}: secret.identity {quote(identity)} is not System or a user-assigned identity's resource ID")
    return out


def _secret_problems(target: str, n: str, s: Obj) -> list[str]:
    return _key_vault_problems(n, s) if target == "containerapps" else _gcp_secret_problems(n, s)


def _gcp_secret_problems(n: str, s: Obj) -> list[str]:
    out: list[str] = []
    secret = s.get("secret")
    if not has_output(secret) and not GCP_SECRET.match(js(secret or "")):
        out.append(f"{n}: secret.secret {quote(secret)} is not a Secret Manager secret ID or projects/PROJECT/secrets/SECRET")
    version = s.get("version") or "latest"
    if not has_output(version) and not GCP_VERSION.match(js(version)):
        out.append(f"{n}: secret.version {quote(version)} is not latest or a version number")
    return out


def target_problems(c: Obj, target: str, args: Obj) -> tuple[list[str], list[str]]:
    """The checks on ecs, cloudrun and containerapps that need no resolved Input."""
    problems: list[str] = []
    warned: list[str] = []
    files = dict(target_files(c, target))
    for k, a in args.items():
        if a is not None and k not in c["vars"] and k not in files:
            problems.append(f"{k}: the {target} target cannot mount this file input" if k in (c.get("files") or {}) else f"{k}: is not declared in the contract")
    for n, v in c["vars"].items():
        a = args.get(n)
        srcs = target_var_sources(v, target)
        if a is None:
            if v.get("required") and not profile_supplies(c, n):
                problems.append(f"{n}: required, but not set (missing_required)")
            continue
        kind = source_of(a, TARGET_SOURCES)
        if kind is None or kind not in srcs:
            problems.append(f"{n}: set exactly one of {or_list(srcs)}{_secret_hint(target, v, srcs)}")
            continue
        s = a[kind]
        if kind == "injected" and is_obj(s):
            if not has_output(s.get("provider")) and not PROVIDER.match(js(s.get("provider") or "")):
                problems.append(f"{n}: injected.provider must name the injector as a lowercase label, such as bank-vaults")
            if s.get("ref") == "":
                problems.append(f"{n}: injected.ref cannot be empty; leave it out when the injector sets the variable itself")
            if s.get("ref") is not None and v["type"] in ("list", "keySet") and v.get("encoding") == "indexed":
                problems.append(f"{n}: an indexed list is spread over NAME__0, NAME__1, …, so one injected reference cannot carry it; let the injector set the variables, without ref")
        if kind == "secret" and is_obj(s):
            if target == "ecs":
                vf = s.get("valueFrom")
                if not has_output(vf):
                    frm = js(vf or "")
                    if not SM_ARN.match(frm) and not SSM_ARN.match(frm) and not BARE_REF.match(frm):
                        problems.append(f"{n}: secret.valueFrom {quote(vf)} is not a Secrets Manager ARN, a Parameter Store ARN, or the name of a secret or parameter")
                    elif any(s.get(k) is not None for k in ("jsonKey", "versionStage", "versionId")) and not SM_ARN.match(frm):
                        problems.append(f"{n}: secret.jsonKey, versionStage and versionId select from a Secrets Manager secret, so secret.valueFrom must be its full ARN")
                if s.get("versionStage") is not None and s.get("versionId") is not None:
                    problems.append(f"{n}: set secret.versionStage or secret.versionId, not both")
            else:
                problems += _secret_problems(target, n, s)
        if v.get("deprecated") and kind != "value":
            warned.append(deprecated_warning(n, v["deprecated"]))
        if kind == "value" and not has_output(s):
            p, w = value_problems(c, n, s)
            problems += p
            warned += w
    for n, f in files.items():
        a = args.get(n)
        if a is None:
            if f.get("required"):
                problems.append(f"{n}: is a required file input; set one of secret or injected")
            continue
        kind = source_of(a, ("secret", "injected"))
        if kind is None:
            frm = "Container Apps mounts files from Key Vault secrets" if target == "containerapps" else "Cloud Run mounts files from Secret Manager"
            problems.append(f"{n}: set exactly one of secret or injected ({frm})")
            continue
        s = a[kind]
        if kind == "injected" and is_obj(s) and not has_output(s.get("provider")) and not PROVIDER.match(js(s.get("provider") or "")):
            problems.append(f"{n}: injected.provider must name the injector as a lowercase label, such as bank-vaults")
        if kind == "secret" and is_obj(s):
            problems += _secret_problems(target, n, s)
        if f.get("deprecated"):
            warned.append(deprecated_warning(n, f["deprecated"]))
    return problems, warned


def render_target(c: Obj, target: str, args: Obj) -> Obj:
    """The ecs, cloudrun and containerapps outputs, for arguments that passed the checks: on
    containerapps, as azure-native's app input dicts, with values escaped."""
    out: Obj = {
        "ecs_environment": [],
        "ecs_secrets": [],
        "cloudrun_env": [],
        "cloudrun_volumes": [],
        "cloudrun_volume_mounts": [],
        "containerapp_env": [],
        "containerapp_secrets": [],
        "containerapp_volumes": [],
        "containerapp_volume_mounts": [],
        "lambda_environment": {},
    }

    def app_secret(name: str, s: Obj) -> Obj:
        return {"name": name, "key_vault_url": s.get("keyVaultSecretId"), "identity": s.get("identity") or "System"}

    for n, v in c["vars"].items():
        a = args.get(n)
        if not is_obj(a):
            continue
        kind = source_of(a, TARGET_SOURCES)
        s = a[kind]
        if kind == "injected":
            ref = s.get("ref")
            if isinstance(ref, str) and ref != "":
                out["ecs_environment"].append({"name": n, "value": ref})
                out["cloudrun_env"].append({"name": n, "value": ref})
                out["containerapp_env"].append({"name": n, "value": esc(ref)})
        elif kind == "secret":
            if target == "ecs":
                out["ecs_secrets"].append({"name": n, "valueFrom": ecs_value_from(s)})
            elif target == "containerapps":
                name = app_secret_name(n, False)
                out["containerapp_secrets"].append(app_secret(name, s))
                out["containerapp_env"].append({"name": n, "secret_ref": name})
            else:
                out["cloudrun_env"].append({"name": n, "value_source": {"secret_key_ref": {"secret": s.get("secret"), "version": s.get("version") or "latest"}}})
        else:
            for en, ev in wire_entries(n, v, s):
                out["ecs_environment"].append({"name": en, "value": ev})
                out["cloudrun_env"].append({"name": en, "value": ev})
                out["containerapp_env"].append({"name": en, "value": esc(ev)})
    out["lambda_environment"] = {e["name"]: e["value"] for e in out["ecs_environment"]}
    for n, f in target_files(c, target):
        a = args.get(n)
        if not is_obj(a):
            continue
        if f.get("pathEnv"):
            out["cloudrun_env"].append({"name": f["pathEnv"], "value": f["path"]})
            out["containerapp_env"].append({"name": f["pathEnv"], "value": esc(f["path"])})
        s = a.get("secret")
        if not is_obj(s):
            continue
        if target == "containerapps":
            name = app_secret_name(n, True)
            out["containerapp_secrets"].append(app_secret(name, s))
            out["containerapp_volumes"].append({"name": f"dc-{n}", "storage_type": "Secret", "secrets": [{"secret_ref": name, "path": posixpath.basename(f["path"])}]})
            out["containerapp_volume_mounts"].append({"volume_name": f"dc-{n}", "mount_path": mount_dir(f)})
            continue
        out["cloudrun_volumes"].append(
            {
                "name": f"dc-{n}",
                "secret": {"secret": s["secret"], "default_mode": 0o400 if f.get("secret") else 0o444, "items": [{"version": s.get("version") or "latest", "path": posixpath.basename(f["path"])}]},
            }
        )
        out["cloudrun_volume_mounts"].append({"name": f"dc-{n}", "mount_path": mount_dir(f)})
    return out


def for_target(self: pulumi.Resource, c: Obj, target: str, args: Mapping[str, Any]) -> Obj:
    """Checks and renders a component's arguments on ecs, cloudrun or containerapps, as kubernetes does for its target."""
    component = f"{c['metadata']['name']} config"
    args = _clean(args)
    problems, warned = target_problems(c, target, args)
    if problems:
        raise ConfigViolation(component, problems)
    for w in warned:
        pulumi.log.warn(w, self)
    names = [*c["vars"], *(n for n, _ in target_files(c, target))]
    checked = _checked_values(self, c, args, names, TARGET_SOURCES)
    def render(r: Obj) -> Obj:
        out = render_target(c, target, r)
        if target == "lambda":
            size = sum(len(k) + len(v) for k, v in out["lambda_environment"].items())
            if size > LAMBDA_ENV_LIMIT:
                raise ConfigViolation(component, [f"the environment variables are {size} bytes, and Lambda allows {LAMBDA_ENV_LIMIT}; move large values to files the function reads, or to Parameter Store"])
        return out

    if target == "lambda" and not has_output(args):
        render(args)  # every value is known: refuse now, not when the outputs resolve

    rendered = (pulumi.Output.all(**checked) if checked else pulumi.Output.from_input({})).apply(render)
    b = {n: {"set": source_of(args.get(n), TARGET_SOURCES) is not None, "source": source_of(args.get(n), TARGET_SOURCES)} for n in names}
    return {"rendered": rendered, "bindings": b, "checked": rendered.apply(lambda _: True)}
